#include <stdio.h>
#include <string.h>
int main(void) {
    static char dd[1000][256];
    int n, q;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) if (scanf("%255s", dd[i]) != 1) return 1;
    if (scanf("%d", &q) != 1) return 1;
    for (int j = 0; j < q; j++) {
        char x[256];
        if (scanf("%255s", x) != 1) return 1;
        int co = 0;
        for (int i = 0; i < n; i++) if (strcmp(dd[i], x) == 0) co = 1;
        printf(co ? "co\n" : "khong\n");
    }
    return 0;
}
